// [LDB-MIR33] The reverse direction (lane Z): records produced by the DynamoDB side apply through the D1-side receiver
// (HMAC ingest, D1 queue table, the same applier) into D1 and give identical rows. The records and the expected rows come from
// tests/mirror/fixtures/reverse.json, generated by apply.test.ts under GEN_REVERSE_FIXTURE=1 (a DynamoDB source run of the fuzzer).
import { env } from "cloudflare:workers";
import { describe, expect, it } from "vitest";
import { runApplier } from "../../src/mirror/apply";
import { handleIngest, signTee } from "../../src/mirror/ingest";
import { d1Kv } from "../../src/mirror/kv-d1";
import { createKvQueue } from "../../src/mirror/queue";
import { TEE_SIG_HEADER, TEE_TS_HEADER, type TeeBatch, type TeeCall } from "../../src/mirror/record";
import { compareMirrored } from "../../scripts/mirror/ops";
import { type RowsByTable } from "../../src/mirror/verify";
import { createD1Store } from "../../src/store/d1";
import fixture from "./fixtures/reverse.json";

const db = (env as unknown as { DB: D1Database }).DB;
const SECRET = "reverse-secret";

async function d1Rows(): Promise<RowsByTable> {
  const { results: tables } = await db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%' AND name <> 'd1_migrations' AND name <> 'mirror_queue'").all<{ name: string }>();
  const out: RowsByTable = {};
  for (const t of tables) out[t.name] = (await db.prepare(`SELECT * FROM ${t.name}`).all<Record<string, unknown>>()).results;
  return out;
}

describe("reverse mirror into D1", () => {
  it("[LDB-MIR33] DynamoDB-side records, out of order and duplicated, apply into D1 to identical rows", async () => {
    const calls = (fixture as unknown as { calls: TeeCall[] }).calls;
    expect(calls.length).toBeGreaterThan(20);
    const queue = createKvQueue(d1Kv(db), "ddb->d1");
    const batches: TeeBatch[] = [];
    for (let i = 0; i < calls.length; i += 4) batches.push({ v: 1, direction: "ddb->d1", batchId: `rv-${i}`, calls: calls.slice(i, i + 4) });
    const post = async (b: TeeBatch) => {
      const body = JSON.stringify(b);
      const ts = String(Math.floor(Date.now() / 1000));
      const h: Record<string, string> = { [TEE_TS_HEADER.toLowerCase()]: ts, [TEE_SIG_HEADER.toLowerCase()]: await signTee(SECRET, ts, body) };
      return handleIngest({ header: (n) => h[n.toLowerCase()] ?? null, body }, { secret: SECRET, queue, nowMs: () => Date.now(), log: () => {} });
    };
    for (const b of [...batches].reverse()) expect((await post(b)).status).toBe(202);
    expect((await post(batches[3]!)).body.duplicate).toBe(true);

    const deps = { store: createD1Store(db), queue, nowMs: () => Date.now() + 3_600_000, settleMs: 0, sleep: async () => {}, log: () => {} };
    let r = await runApplier(deps);
    for (let i = 0; i < 100 && r.applied + r.skipped > 0; i++) r = await runApplier(deps);
    const div = await queue.readDivergent();
    expect(r.halted, JSON.stringify((div as { mismatch?: unknown } | null)?.mismatch)?.slice(0, 2500)).toBeNull();
    expect((await queue.readState()).appliedSeq).toBe(Math.max(...calls.flatMap((c) => c.seqs)));
    expect(await queue.pending(3)).toEqual([]);
    expect(compareMirrored((fixture as unknown as { rows: RowsByTable }).rows, await d1Rows())).toEqual([]);
  }, 120_000);
});
